// CommuLingo guided reading (format 'guided-reading', 2026-10-24): each lesson
// shows a passage of the site's full translation first, then one question on
// it. Korean passages are verbatim from the document marx-civil-war-in-france
// (scripts/check-course-source-excerpts.js checks them and their anchors).
// English passages are verbatim from Marx's English original; Engels's 1891
// introduction is German, so its English passages are translated here from
// the German text the document carries. A passage may skip text with ' … '.

function t(ko, en) {
    return { ko, en };
}

const DOC = '/commulingo/docs/marx-civil-war-in-france';
const BOOK = 'marx-civil-war-in-france';

const LABELS = {
    'engels-introduction-1891': t('엥겔스, 1891년 판 서문', 'Engels, introduction to the 1891 edition (our translation from the German)'),
    'first-address-1870': t('보불전쟁에 관한 첫 번째 담화 (1870년 7월 23일)', 'First Address on the war (23 July 1870)'),
    'second-address-1870': t('보불전쟁에 관한 두 번째 담화 (1870년 9월 9일)', 'Second Address on the war (9 September 1870)'),
    'cwf-1': t('『프랑스 내전』 제1절', 'The Civil War in France, section I'),
    'cwf-2': t('『프랑스 내전』 제2절', 'The Civil War in France, section II'),
    'cwf-3': t('『프랑스 내전』 제3절', 'The Civil War in France, section III'),
    'cwf-4': t('『프랑스 내전』 제4절', 'The Civil War in France, section IV'),
};

function passage(anchor, contextKo, contextEn, quoteKo, quoteEn) {
    return {
        context: t(contextKo, contextEn),
        source: { href: `${DOC}#${anchor}`, label: LABELS[anchor], quote: t(quoteKo, quoteEn) },
    };
}

// Choices and their feedback are authored correct answer first, which is how
// they are stored (answer 0); the player shuffles them for display.
function q(where, koPrompt, enPrompt, koChoices, enChoices, koExplanation, enExplanation, koFeedback, enFeedback) {
    return {
        type: 'multiple_choice',
        points: 0,
        context: where.context,
        prompt: t(koPrompt, enPrompt),
        choices: { ko: koChoices, en: enChoices },
        answer: 0,
        explanation: t(koExplanation, enExplanation),
        choiceFeedback: { ko: koFeedback, en: enFeedback },
        source: where.source,
    };
}

function chapter(ch, anchor, titleKo, titleEn, summaryKo, summaryEn, questions) {
    const id = `${BOOK}-ch${String(ch).padStart(2, '0')}`;
    return {
        id,
        volumeNumber: 16,
        chapterNumber: ch,
        title: t(titleKo, titleEn),
        sourceUrl: `${DOC}#${anchor}`,
        summary: t(summaryKo, summaryEn),
        lessons: [{
            id: `${id}-basic`,
            level: 'basic',
            title: t(titleKo, titleEn),
            questions: questions.map((item, index) => ({ ...item, id: `q${index + 1}`, points: 2 })),
        }],
    };
}

